    var fields: [String] = []
    var current = ""
    var inQuotes = false
    var i = line.startIndex

    while i < line.endIndex {
        let ch = line[i]

        if ch == "\"" {
            if inQuotes {
                let next = line.index(after: i)
                if next < line.endIndex && line[next] == "\"" {
                    current.append("\"")
                    i = line.index(after: next)
                    continue
                } else {
                    inQuotes = false
                }
            } else {
                inQuotes = true
            }
        } else if ch == "," && !inQuotes {
            fields.append(current)
            current = ""
        } else {
            current.append(ch)
        }

        i = line.index(after: i)
    }

    fields.append(current)
    return fields
}

