    unsigned char *buf = malloc(BUF_SIZE);
    if (!buf) { fclose(f); return -1; }
    long bytes = 0;
    long line_count = 0;
    int last = -1;
    size_t n;
    while ((n = fread(buf, 1, BUF_SIZE, f)) > 0) {
        bytes += (long)n;
        for (size_t i = 0; i < n; i++) {
            if (buf[i] == '\n') line_count++;
        }
        last = buf[n - 1];
    }
    if (ferror(f)) {
        fclose(f);
        free(buf);
        return -1;
    }
    fclose(f);
    if (bytes > 0 && last != '\n') {
        line_count++;
    }
    *lines = line_count;
    *chars = bytes;
    free(buf);
    return 0;
}

