const A: number[][] = [[1, 2, 3], [4, 5, 6], [7, 8, 9]];
const B: number[][] = [[9, 8, 7], [6, 5, 4], [3, 2, 1]];

function multiply(a: number[][], b: number[][]): number[][] {
  const rows = a.length;
  const cols = b[0].length;
  const inner = b.length;
  const result: number[][] = [];

  for (let i = 0; i < rows; i++) {
    result[i] = [];
    for (let j = 0; j < cols; j++) {
      let sum = 0;
      for (let k = 0; k < inner; k++) {
        sum += a[i][k] * b[k][j];
      }
      result[i][j] = sum;
    }
  }

  return result;
}

function determinant3(m: number[][]): number {
  return (
    m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1]) -
    m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0]) +
    m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0])
  );
}

function pad4(v: number): string {
  const s = String(v);
  let padding = "";
  for (let i = s.length; i < 4; i++) {
    padding += " ";
  }
  return padding + s;
}

function formatMatrix(m: number[][]): string {
  return m.map(row => "  " + row.map(v => pad4(v)).join(" ")).join("\n");
}

